package ru.mcsa.bukkit;
// Разделители путей и формата не требуют запуска регулярных выражений в Wasm.
public final class Strings {
 // ASCII-пути Locale.ROOT не требуют холодной загрузки таблиц Unicode.
 public static String lower(String value,java.util.Locale locale){java.util.Objects.requireNonNull(locale);if(locale==java.util.Locale.ROOT&&ascii(value)){String result=Ascii.lower(value);return result.equals(value)?value:result;}return value.toLowerCase(locale);}
 public static String upper(String value,java.util.Locale locale){java.util.Objects.requireNonNull(locale);if(locale==java.util.Locale.ROOT&&ascii(value)){String result=Ascii.upper(value);return result.equals(value)?value:result;}return value.toUpperCase(locale);}
 private static boolean ascii(String value){for(int i=0;i<value.length();i++)if(value.charAt(i)>127)return false;return true;}

 // Мост передаёт UTF-8 без создания CharsetEncoder для каждого маленького запроса.
 public static byte[] utf8(String value){int length=0;for(int i=0;i<value.length();i++){char c=value.charAt(i);if(c<128)length++;else if(c<2048)length+=2;else if(c>=0xd800&&c<=0xdbff&&i+1<value.length()&&value.charAt(i+1)>=0xdc00&&value.charAt(i+1)<=0xdfff){length+=4;i++;}else length+=c>=0xd800&&c<=0xdfff?1:3;}byte[] out=new byte[length];int at=0;for(int i=0;i<value.length();i++){int c=value.charAt(i);if(c<128)out[at++]=(byte)c;else if(c<2048){out[at++]=(byte)(0xc0|(c>>6));out[at++]=(byte)(0x80|(c&63));}else if(c>=0xd800&&c<=0xdbff&&i+1<value.length()&&value.charAt(i+1)>=0xdc00&&value.charAt(i+1)<=0xdfff){c=0x10000+((c-0xd800)<<10)+(value.charAt(++i)-0xdc00);out[at++]=(byte)(0xf0|(c>>18));out[at++]=(byte)(0x80|((c>>12)&63));out[at++]=(byte)(0x80|((c>>6)&63));out[at++]=(byte)(0x80|(c&63));}else if(c>=0xd800&&c<=0xdfff)out[at++]='?';else {out[at++]=(byte)(0xe0|(c>>12));out[at++]=(byte)(0x80|((c>>6)&63));out[at++]=(byte)(0x80|(c&63));}}return out;}
 private static int continuation(byte[] bytes,int at){if(at>=bytes.length||(bytes[at]&0xc0)!=0x80)throw new IllegalStateException("Повреждённый UTF-8 хозяина");return bytes[at]&63;}
 public static String fromUtf8(byte[] bytes){char[] out=new char[bytes.length];int count=0;for(int i=0;i<bytes.length;){int c=bytes[i++]&255;if(c<128){out[count++]=(char)c;continue;}int code;if(c>=0xc2&&c<=0xdf){code=((c&31)<<6)|continuation(bytes,i++);}else if(c>=0xe0&&c<=0xef){int b=continuation(bytes,i++);code=((c&15)<<12)|(b<<6)|continuation(bytes,i++);if(code<0x800||code>=0xd800&&code<=0xdfff)throw new IllegalStateException("Повреждённый UTF-8 хозяина");}else if(c>=0xf0&&c<=0xf4){code=((c&7)<<18)|(continuation(bytes,i++)<<12)|(continuation(bytes,i++)<<6)|continuation(bytes,i++);if(code<0x10000||code>0x10ffff)throw new IllegalStateException("Повреждённый UTF-8 хозяина");}else throw new IllegalStateException("Повреждённый UTF-8 хозяина");if(code<0x10000)out[count++]=(char)code;else {code-=0x10000;out[count++]=(char)(0xd800+(code>>10));out[count++]=(char)(0xdc00+(code&1023));}}return new String(out,0,count);}

 public static String[] split(String value,char separator){java.util.List<String> out=new java.util.ArrayList<>();int from=0;for(int i=0;i<=value.length();i++)if(i==value.length()||value.charAt(i)==separator){out.add(value.substring(from,i));from=i+1;}return out.toArray(new String[0]);}
}
